<?php require '../common.php';startpage('Book Bus Ticket');nav('<a href="index.php">Search</a>');$id=(int)($_GET['id']??$_POST['id']??0);$s=$conn->prepare('SELECT * FROM buses WHERE id=?');$s->bind_param('i',$id);$s->execute();$bus=$s->get_result()->fetch_assoc();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&$bus){$name=trim($_POST['passenger']);$n=max(1,(int)$_POST['seats']);$u=$conn->prepare('UPDATE buses SET available_seats=available_seats-? WHERE id=? AND available_seats>=?');$u->bind_param('iii',$n,$id,$n);$u->execute();if($name&&$u->affected_rows===1){$i=$conn->prepare('INSERT INTO bus_bookings(passenger,bus_id,seats) VALUES(?,?,?)');$i->bind_param('sii',$name,$id,$n);$i->execute();$msg='Ticket booked.';}else{$conn->query("UPDATE buses SET available_seats=available_seats+$n WHERE id=$id");$msg='Not enough seats or invalid name.';}}if($bus):?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><p><?=e($bus['bus_name'])?>: <?=e($bus['origin'])?> to <?=e($bus['destination'])?></p><input name="passenger" placeholder="Passenger name" required><input type="number" name="seats" min="1" max="<?=$bus['available_seats']?>" value="1"><button>Book ticket</button></form><?php endif;if($msg)echo '<p class="msg">'.e($msg).'</p>';endpage();?>